import{_ as r,l as o,o as e,c as s,v as i,p as n,x as t,d as h,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"曝光动力学与光酸生成","description":"","frontmatter":{"title":"曝光动力学与光酸生成","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/exposure-kinetics-acid.md","filePath":"litho/exposure-kinetics-acid.md","lastUpdated":1789023840000}'),d={name:"litho/exposure-kinetics-acid.md"};function E(P,a,c,B,_,m){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="曝光动力学与光酸生成" tabindex="-1">曝光动力学与光酸生成 <a class="header-anchor" href="#曝光动力学与光酸生成" aria-label="Permalink to &quot;曝光动力学与光酸生成&quot;">​</a></h1><div class="epigraph"><p>Dill 的 $C$ 写出 PAC 怎么被消耗；化学放大还要把同一段曝光读成酸的出生。动力学在曝光结束时停止，催化不在这里开始。</p><footer>—— 据 Dill 曝光方程与 Ito / Willson 产酸接口；Mack 对 PAC/PAG 转化的表述整理</footer></div><p><a href="/litho/dill-parameters">上一课</a>把 \\(A\\)、\\(B\\)、\\(C\\) 钉成胶内吸收与 \\(m\\) 的速率。缺口是：<a href="/litho/car-resist">CAR</a> 的潜像不是抑制剂分数，而是酸浓度。本课把曝光动力学接到光酸生成。<a href="/litho/pag-quencher">PAG 与淬灭剂</a>已经说明酸从哪来、碱钉阈值；这里只补曝光时段的速率，不重写那一对配方旋钮。PEB 里酸怎么走，留给<a href="/litho/peb-reaction-diffusion">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Dill 方程的 \\(m\\) 对 DNQ 就是 PAC 分数。CAR 里对应物是未转化 PAG 分数：曝光把 PAG 打成酸（DUV 上直接或经敏化；EUV 上经二次电子，本课先承认路径不同，不写截面表）。低剂量、无耗尽时，酸浓度近似与吸收能量成正比，看起来像「\\(C\\) 乘剂量」。剂量高了，PAG 耗尽，\\(m\\) 指数下降，产酸饱和——这是曝光动力学，不是 PEB 增益。</p><p>缺口因此是：把上一课的 \\(\\partial m/\\partial t=-CIm\\) 读成酸源项 \\(h=h_0(1-m)\\)（或等价的 PAG 转化分数），并声明淬灭剂在曝光结束时几乎还没动。把酸图直接写成空中像 \\(I(x)\\)，等于假定转化永远线性、碱为零。</p><h3 id="曝光结束-催化尚未开始" tabindex="-1">曝光结束，催化尚未开始 <a class="header-anchor" href="#曝光结束-催化尚未开始" aria-label="Permalink to &quot;曝光结束，催化尚未开始&quot;">​</a></h3><p>室温下脱保护速率通常可以忽略。扫描狭缝走过之后，晶圆上只有酸与剩余 PAG、预置碱。Ito / Willson 的放大发生在后烘。本课禁止用「化学增益」解释曝光时段的灵敏度：增益还没开机。</p><p><span class="marginnote">EUV 一次 92 eV 吸收可经电离产多颗酸，有效「量子产率」可以大于 1，仍是曝光事件，不是 PEB 循环。Kozawa 的电离路径改的是本课源项的预因子，不改「曝光写酸、PEB 用酸」的分工。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>紧凑写法：指定 \\(C\\) 与初始 PAG 加载，沿狭缝时间积分 \\(I(x,z,t)\\)，得到转化分数与酸浓度 \\(h(x,z)\\)。漂白若 \\(A\\neq 0\\)，必须与强度联立，否则底部酸会被高估。表征：用 \\(E_0\\) 扫胶、或用指示剂看产酸，但 \\(E_0\\) 还含显影与 PEB，不能单独反解 \\(C\\)——标定要固定后烘再拆。</p><p>与<a href="/litho/pag-quencher">淬灭剂</a>的接口：曝光模块输出的是生成酸；有效酸要等下一课中和。本课可以承认「碱在膜里」，但速率方程仍把中和留给 PEB 温度下的扩散–反应。把中和写进曝光积分，等于给室温一个虚假的催化时钟。</p>',12)),(e(),n(A,null,{default:t(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22I(x%2Cz)%20Dill%20%E8%BE%93%E5%85%A5%22%5D%20--%3E%20C%5B%22C%20%E8%BD%AC%E5%8C%96%20PAG%22%5D%0A%20%20C%20--%3E%20H%5B%22%E7%94%9F%E6%88%90%E9%85%B8%20h%22%5D%0A%20%20PAG%5B%22PAG%20%E5%8A%A0%E8%BD%BD%22%5D%20--%3E%20H%0A%20%20H%20--%3E%20PEB%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E5%8F%8D%E5%BA%94%E6%89%A9%E6%95%A3%22%5D%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%E5%BA%93%E5%AD%98%22%5D%20--%3E%20PEB%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>DUV：光子把鎓盐 PAG 打成超强酸，量子效率通常小于 1，受聚合物吸收分流——上一课的 \\(B\\) 并不全是 PAG。酸一旦生成，在曝光时间尺度上基本钉在出生点附近；室温扩散长度远小于 PEB 的 \\(\\ell\\)。EUV：吸收截面由高 Z 与聚合物共同决定，二次电子把能量交给 PAG，源项在空间上已经带一颗纳米核——那颗核的模型是随机课序的题目，本课只把平均产酸写进 \\(h\\)。</p><p>线性区：\\(h\\propto(1-e^{-CE})\\) 一类饱和形式（细节随是否用剂量还是局部强度积分而变）。OPC 紧凑胶若用「有效剂量 × 灵敏度」，等于取了这个函数的切线；PAG 耗尽或漂白强时切线撒谎。</p><p><span class="marginnote">不要把「更敏」写成更大的 \\(C\\)。加 PAG 加载、加 PEB、减淬灭都能降 \\(E_0\\)，只有第一种主要改本课的源项幅度。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 PAG 分子式，不把某胶的量子产率当节点规格。不重推 CAR 循环——<a href="/litho/car-resist">化学放大</a>已经钉过。下一课默认本课交出平均酸图 \\(h(x,z)\\)，再在 PEB 温度下做反应–扩散。随机计数把 \\(h\\) 换成离散分子，那是后一单元；本课仍是连续场。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>曝光动力学把 Dill \\(C\\) 读成 PAG 转化与酸源项；催化不在曝光里。</li><li>低剂量近线性，高剂量 PAG 耗尽饱和。</li><li>淬灭剂库存带到 PEB，不在室温积分里被「用掉」。</li><li>EUV 电离可让每光子酸数 \\(\\gt 1\\)，仍属曝光源项。</li><li>「更敏」未必是更大的 \\(C\\)。</li><li>出处：Dill 曝光方程；Ito / Willson 产酸；Mack 教材中的 PAG 转化。</li></ul>',8))])}const f=r(d,[["render",E]]);export{C as __pageData,f as default};
